def predecessor():
    source = zlib.decompress(base64.b64decode(LEGACY, validate=True))
    if hashlib.sha256(source).hexdigest() != LEGACY_SHA:
        raise RuntimeError("Embedded predecessor hash mismatch")
    module = types.ModuleType("reviewed_warning_controls_operator")
    exec(compile(source, "<reviewed predecessor>", "exec"), module.__dict__)
    module.REVIEWED_SOURCE_SHA.update(PREVIOUS_ADS_SOURCE_SHA)
    hashes = dict(module.REVIEWED_SOURCE_SHA[module.NEW])
    hashes.update({name: entry["sha256"] for name, entry in PAYLOAD.items()})
    module.REVIEWED_SOURCE_SHA[CODE_HEAD] = hashes
    module.NEW = CODE_HEAD
    return module


def incoming(base):
    result = base.incoming()
    for name, entry in PAYLOAD.items():
        if ".." in Path(name).parts or not (
            name.startswith("app/")
            or name
            in {
                "migrations/versions/0020_unified_auto_ads.py",
                "migrations/versions/0021_group_warning_settings.py",
                "migrations/versions/0022_group_checks.py",
                "migrations/versions/0023_group_help_controls.py",
                "migrations/versions/0024_merchant_directory.py",
            }
        ):
            raise RuntimeError("Unexpected AUTO ADS destination")
        content = zlib.decompress(base64.b64decode(entry["content"], validate=True))
        if hashlib.sha256(content).hexdigest() != entry["sha256"]:
            raise RuntimeError("AUTO ADS content hash mismatch")
        compile(content, name, "exec")
        result[name] = content
    return result


def runtime_for(base, kit, client_id=None):
    source = base.guarded_runtime(kit)
    old = "        if chat is not None and chat not in {-1004454398792,28563234}:raise PermissionError('Outside test allowlist')"
    allowed = {-1004454398792, 28563234}
    if client_id:
        allowed.add(client_id)
    new = f"        if chat is not None and chat not in {sorted(allowed)!r}:raise PermissionError('Outside test allowlist')"
    if source.count(old) != 1:
        raise RuntimeError("Unknown Telegram staging boundary")
    source = source.replace(old, new)
    compile(source, "<AUTO ADS staging runtime>", "exec")
    return source


def verify_runtime(base, kit, context):
    path = kit.ROOT / "runtime" / "runtime.py"
    if path.is_symlink() or not path.is_file():
        raise RuntimeError("Unsafe runtime")
    source = path.read_text()
    allowed = {kit.RUNTIME, base.guarded_runtime(kit)}
    if context["head"] in {CODE_HEAD, *PREVIOUS_ADS_SOURCE_SHA}:
        allowed.add(runtime_for(base, kit, context.get("auto_ads_client_id")))
    if source not in allowed:
        raise RuntimeError("Unreviewed test runtime; no process stopped")
    return source


def client_for(requested, context):
    """A code-only update preserves the already approved private test boundary."""
    client = requested if requested is not None else context.get("auto_ads_client_id")
    if client is not None and (type(client) is not int or client <= 0 or client == 8986848376):
        raise RuntimeError("Use a consenting human test account numeric ID")
    return client


WORK_SQL = """BEGIN READ ONLY;
SELECT json_build_object(
 'schema',(SELECT version_num FROM alembic_version),
 'groups',(SELECT count(*) FROM managed_groups WHERE chat_id=-1004454398792),
 'active_ads',(SELECT count(*) FROM ad_schedules s
   JOIN ad_campaigns c ON c.id=s.campaign_id
   WHERE s.status='ACTIVE' AND c.status='DRAFT' AND NOT s.excluded),
 'archived_active_schedules',(SELECT count(*) FROM ad_schedules s
   JOIN ad_campaigns c ON c.id=s.campaign_id
   WHERE s.status='ACTIVE' AND c.status='ARCHIVED'),
 'publications',(SELECT count(*) FROM ad_publication_attempts
   WHERE status IN ('PENDING','CLAIMED','SENDING','DEFERRED','UNCERTAIN')),
 'ambiguous_sanctions',(SELECT count(*) FROM group_sanctions
   WHERE status IN ('PENDING','REVOKING','UNCERTAIN')),
 'jobs',(SELECT count(*) FROM group_sanction_jobs
   WHERE status IN ('PENDING','PROCESSING','UNCERTAIN')),
 'active_sanctions',(SELECT count(*) FROM group_sanctions WHERE status='ACTIVE')
); COMMIT;"""


def idle(base, kit, *, require_idle=True):
    value = base.database_json(kit, WORK_SQL)
    if value["schema"] not in {
        "0016",
        "0017",
        "0018",
        "0019",
        "0020",
        "0021",
        "0022",
        "0023",
        "0024",
    }:
        raise RuntimeError("Unexpected staging schema")
    if value["schema"] in {"0022", "0023", "0024"}:
        checks = base.database_json(
            kit,
            "BEGIN READ ONLY; SELECT json_build_object('checks_pending',count(*)) FROM group_check_events WHERE state IN ('PENDING','WAITING','SENDING','QUEUED'); COMMIT;",
        )
        value["checks_pending"] = checks["checks_pending"]
    if value["groups"] != 1:
        raise RuntimeError("Approved test group missing; no groups created automatically")
    if require_idle and (
        value.get("checks_pending", 0)
        or any(value[k] for k in ("active_ads", "publications", "ambiguous_sanctions", "jobs"))
    ):
        raise RuntimeError(
            "Test work needs review: "
            + json.dumps(value, sort_keys=True)
            + "; pause scheduled ads in the existing test bot; no state deleted"
        )
    print(
        "ReadOnlyWorkCheck=PASS; ConfirmedActiveSanctionsPreserved="
        + str(value["active_sanctions"])
        + "; ArchivedActiveSchedulesIgnored="
        + str(value.get("archived_active_schedules", 0)),
        flush=True,
    )
    return value


